package com.aicharacter.v3;
/** Feline balance reflexes sense paw support/slip and constrain locomotion without overriding player intent. */
public final class CatNervousSystemEngine{private CatNervousSystemEngine(){}
 public static void advance(WorldState s,double dt,long now){if(s==null||dt<=0)return;if(s.catNervous==null)s.catNervous=new CatNervousState();CatNervousState n=s.catNervous;PhysicsBodyState p=s.catPhysics;CatRigState r=s.catRig;if(p==null||r==null)return;double support=Math.max(.04,p.supportRight-p.supportLeft),center=(p.supportLeft+p.supportRight)*.5,half=support*.5,edge=Math.max(0,Math.abs(p.centerOfMassX-center)-half*.75)/Math.max(.025,half*.7),contacts=(r.frontLeftContact+r.frontRightContact+r.hindLeftContact+r.hindRightContact)/4.0,maxSlip=Math.max(Math.max(r.frontLeftSlip,r.frontRightSlip),Math.max(r.hindLeftSlip,r.hindRightSlip)),slipAsym=Math.max(Math.abs(r.frontLeftSlip-r.frontRightSlip),Math.abs(r.hindLeftSlip-r.hindRightSlip));double err=cl(edge*.68+(1-contacts)*.38+maxSlip*.62+slipAsym*.28+p.landingInstability*.5);n.proprioceptiveError=follow(n.proprioceptiveError,err,dt,.07);n.balanceAlarm=follow(n.balanceAlarm,cl((1-p.balance)*.68+n.proprioceptiveError*.62),dt,.055);n.motorCorrection=follow(n.motorCorrection,cl(n.balanceAlarm*.82+n.proprioceptiveError*.52),dt,.045);n.recoveryDrive=follow(n.recoveryDrive,cl(maxSlip*.72+(1-contacts)*.65+n.motorCorrection*.55),dt,.05);n.fallBrace=follow(n.fallBrace,p.grounded?0:Math.min(1,Math.abs(p.velocityY)/3.8),dt,.045);if(p.grounded)p.landingInstability=Math.max(0,p.landingInstability-dt*(.38+n.motorCorrection*.5));n.lastUpdatedAt=Math.max(n.lastUpdatedAt,now);}
 public static void observePostMotorSupport(WorldState s,double dt,long now){if(s==null||dt<=0||s.catNervous==null||s.catPhysics==null||s.catRig==null)return;CatNervousState n=s.catNervous;PhysicsBodyState p=s.catPhysics;CatRigState r=s.catRig;double support=Math.max(.04,p.supportRight-p.supportLeft),center=(p.supportLeft+p.supportRight)*.5,half=support*.5,edge=Math.max(0,Math.abs(p.centerOfMassX-center)-half*.75)/Math.max(.025,half*.7),contacts=(r.frontLeftContact+r.frontRightContact+r.hindLeftContact+r.hindRightContact)/4.0,maxSlip=Math.max(Math.max(r.frontLeftSlip,r.frontRightSlip),Math.max(r.hindLeftSlip,r.hindRightSlip)),recovery=(Double.isFinite(r.frontLeftRecoveryX)?1:0)+(Double.isFinite(r.frontRightRecoveryX)?1:0)+(Double.isFinite(r.hindLeftRecoveryX)?1:0)+(Double.isFinite(r.hindRightRecoveryX)?1:0);double post=cl(edge*.72+(1-contacts)*.5+maxSlip*.52+recovery*.14);double senseDt=Math.min(dt,.12);n.proprioceptiveError=follow(n.proprioceptiveError,Math.max(n.proprioceptiveError,post),senseDt,.045);n.balanceAlarm=follow(n.balanceAlarm,cl(Math.max(1-p.balance,n.proprioceptiveError)*.8),senseDt,.045);n.motorCorrection=follow(n.motorCorrection,cl(n.balanceAlarm*.86+n.proprioceptiveError*.54),senseDt,.04);n.recoveryDrive=follow(n.recoveryDrive,cl(Math.max(post,n.motorCorrection)),senseDt,.04);n.lastUpdatedAt=Math.max(n.lastUpdatedAt,now);}
 public static double locomotorConstraint(WorldState s){CatNervousState n=s==null?null:s.catNervous;return n==null?1:Math.max(.34,1-n.balanceAlarm*.42-n.recoveryDrive*.28);}
 private static double follow(double v,double t,double dt,double tau){double k=1-Math.exp(-Math.min(dt,.25)/Math.max(.02,tau));return cl(v+(t-v)*k);}private static double cl(double v){return Math.max(0,Math.min(1,v));}
}
